"""Codex permission-profile config for isolated RAPID workspaces."""

from __future__ import annotations

import json
import os
import shutil
import sys
import tomllib
from pathlib import Path
from typing import Iterable, Mapping, Sequence

from suites.staged.experiment_paths import experiment_root


PROFILE_NAME = "rapid-experiment"
GENERATED_HEADER = (
    "# Generated by RAPID. Do not edit by hand; launchers may refresh this file.\n"
)
RUN_CODEX_HOME_NAME = "codex_home"
BOOTSTRAP_TOP_LEVEL_KEYS = (
    "model_provider",
    "openai_base_url",
    "preferred_auth_method",
    "cli_auth_credentials_store",
)


def _toml_string(value: object) -> str:
    return json.dumps(str(value))


def _toml_key(value: object) -> str:
    return _toml_string(value)


def _toml_value(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int | float):
        return str(value)
    if isinstance(value, list):
        return "[" + ", ".join(_toml_value(item) for item in value) + "]"
    return _toml_string(value)


def _append_toml_table(
    lines: list[str],
    table: Mapping[str, object],
    *,
    path: Sequence[str],
) -> None:
    scalar_items: list[tuple[str, object]] = []
    child_tables: list[tuple[str, Mapping[str, object]]] = []
    for key, value in sorted(table.items()):
        if isinstance(value, Mapping):
            child_tables.append((key, value))
        else:
            scalar_items.append((key, value))

    if scalar_items:
        lines.append("")
        lines.append("[" + ".".join(_toml_key(part) for part in path) + "]")
        for key, value in scalar_items:
            lines.append(f"{_toml_key(key)} = {_toml_value(value)}")

    for key, value in child_tables:
        _append_toml_table(lines, value, path=[*path, key])


def _path_is_under(child: Path, parent: Path) -> bool:
    try:
        child.relative_to(parent)
    except ValueError:
        return child == parent
    return True


def path_overlaps(left: Path, right: Path) -> bool:
    return _path_is_under(left, right) or _path_is_under(right, left)


def path_exposes_blocked_checkpoint(path: Path, *, repo_root: Path, workspace: Path) -> bool:
    """Return true if a read grant would expose hidden RAPID experiment state."""
    path = path.expanduser().resolve()
    repo_root = repo_root.expanduser().resolve()
    workspace = workspace.expanduser().resolve()
    if _path_is_under(path, workspace):
        return False

    for blocked in (
        repo_root / "benchmark_private",
        repo_root / "workspace" / "src",
        repo_root / "demos",
        repo_root / "tasks",
        repo_root / "suite_runs",
        experiment_root(repo_root),
        repo_root / "runtime_assets" / "benchmark_hope_v1",
    ):
        if blocked.exists() and path_overlaps(path, blocked.resolve()):
            return True
    return False


def inspect_conda_root() -> Path:
    """Return the conda installation root for the active Python interpreter."""
    python = Path(sys.executable).resolve()
    conda_prefix = Path(os.environ.get("CONDA_PREFIX") or python.parents[1]).resolve()
    if conda_prefix.parent.name == "envs":
        return conda_prefix.parent.parent.resolve()
    return conda_prefix


def _existing_paths(paths: Iterable[Path]) -> list[Path]:
    existing: list[Path] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.expanduser().resolve()
        if not resolved.exists() or resolved in seen:
            continue
        existing.append(resolved)
        seen.add(resolved)
    return existing


def codex_cli_runtime_read_grants() -> list[Path]:
    """Read grants for the installed Codex CLI package and native helper."""
    paths: list[Path] = []
    codex_path = shutil.which("codex")
    if codex_path:
        resolved = Path(codex_path).expanduser().resolve()
        package_root: Path | None = None
        for parent in resolved.parents:
            if parent.name == "codex" and parent.parent.name == "@openai":
                package_root = parent
                break
            if parent.name.startswith("codex-") and parent.parent.name == "@openai":
                package_root = parent
                break
        paths.append(package_root or resolved)
        if package_root is not None and package_root.name == "codex":
            # npm installs platform binaries alongside the JavaScript launcher.
            paths.extend(
                vendor.parent
                for vendor in sorted(package_root.parent.glob("codex-*/vendor"))
                if vendor.is_dir()
            )

    managed_package_root = os.environ.get("CODEX_MANAGED_PACKAGE_ROOT")
    if managed_package_root:
        paths.append(Path(managed_package_root))
    return _existing_paths(paths)


def codex_arg0_helper_read_grants(codex_home: Path) -> list[Path]:
    """Read grants for Codex's per-run arg0 helper symlink directory."""
    arg0_dir = codex_home.expanduser().resolve() / "tmp" / "arg0"
    arg0_dir.mkdir(parents=True, exist_ok=True)
    return [arg0_dir]


def run_codex_home_path(workspace: Path) -> Path:
    return workspace.expanduser().resolve().parent / RUN_CODEX_HOME_NAME


def run_codex_helper_path(workspace: Path) -> Path:
    return run_codex_home_path(workspace) / "tmp" / "arg0"


def stable_read_grants(repo_root: Path, conda_root: Path | None = None) -> list[Path]:
    """Read grants needed by generated agents independent of a specific task."""
    repo_root = repo_root.expanduser().resolve()
    paths = [
        repo_root / "scripts",
        repo_root / "agent",
        repo_root / "AGENTS.md",
        repo_root / "SUITE_RUNS.md",
        repo_root / "runtime_assets" / "fr3" / "fr3_task_v1",
    ]
    judo = repo_root / "third_party" / "judo"
    if (judo / "judo").is_dir():
        paths.append(judo)
    if conda_root is not None:
        paths.append(conda_root)
    if Path("/opt").exists():
        paths.append(Path("/opt"))
    paths.extend(codex_cli_runtime_read_grants())
    return _existing_paths(paths)


def safe_pythonpath_read_grants(
    pythonpath: str,
    *,
    repo_root: Path,
    workspace: Path,
) -> list[Path]:
    """Return caller PYTHONPATH entries that do not reveal hidden checkpoints."""
    grants: list[Path] = []
    for raw in pythonpath.split(os.pathsep):
        if not raw:
            continue
        path = Path(raw).expanduser()
        if not path.exists():
            continue
        resolved = path.resolve()
        if path_exposes_blocked_checkpoint(
            resolved,
            repo_root=repo_root,
            workspace=workspace,
        ):
            continue
        grants.append(resolved)
    return _existing_paths(grants)


def host_tool_read_grants(tools: Sequence[str], *, conda_root: Path) -> list[Path]:
    """Read grants for host tools installed outside common system or conda paths."""
    grants: list[Path] = []
    for tool in tools:
        tool_path = shutil.which(tool)
        if not tool_path:
            continue
        resolved = Path(tool_path).resolve()
        if _path_is_under(resolved, conda_root):
            continue
        if str(resolved).startswith(("/usr/", "/bin/", "/sbin/")):
            continue
        grants.append(resolved)
        lib_dir = resolved.parent.parent / "lib"
        if lib_dir.is_dir():
            grants.append(lib_dir)
    return _existing_paths(grants)


def write_workspace_codex_config(
    workspace: Path,
    *,
    repo_root: Path,
    read_grants: Sequence[Path] = (),
    allowed_blocked_read_grants: Sequence[Path] = (),
    workspace_write_grants: Sequence[Path] | None = None,
    workspace_read_overrides: Sequence[Path] = (),
    conda_root: Path | None = None,
) -> Path:
    """Write the workspace-local Codex permission profile."""
    workspace = workspace.expanduser().resolve()
    repo_root = repo_root.expanduser().resolve()
    conda_root = conda_root or inspect_conda_root()
    run_helper = run_codex_helper_path(workspace)
    run_helper.mkdir(parents=True, exist_ok=True)
    all_read_grants = _existing_paths(
        [
            *stable_read_grants(repo_root, conda_root),
            run_helper,
            *read_grants,
            *allowed_blocked_read_grants,
        ]
    )
    allowed_blocked = set(_existing_paths([run_helper, *allowed_blocked_read_grants]))
    allowed_read_grants = [
        path
        for path in all_read_grants
        if path in allowed_blocked
        or not path_exposes_blocked_checkpoint(
            path,
            repo_root=repo_root,
            workspace=workspace,
        )
    ]
    relative_write_grants: list[str] = []
    if workspace_write_grants is not None:
        for path in workspace_write_grants:
            candidate = path.expanduser()
            if not candidate.is_absolute():
                candidate = workspace / candidate
            resolved = candidate.resolve()
            try:
                relative = resolved.relative_to(workspace)
            except ValueError as exc:
                raise ValueError(
                    f"workspace write grant escapes workspace: {path}"
                ) from exc
            if relative == Path("."):
                raise ValueError(
                    "restricted workspace write grants cannot include "
                    "the workspace root"
                )
            value = relative.as_posix()
            if value not in relative_write_grants:
                relative_write_grants.append(value)
    relative_read_overrides: list[str] = []
    for path in workspace_read_overrides:
        candidate = path.expanduser()
        if not candidate.is_absolute():
            candidate = workspace / candidate
        resolved = candidate.resolve()
        try:
            relative = resolved.relative_to(workspace)
        except ValueError as exc:
            raise ValueError(
                f"workspace read override escapes workspace: {path}"
            ) from exc
        if relative == Path("."):
            raise ValueError(
                "workspace read overrides cannot include the workspace root"
            )
        value = relative.as_posix()
        if value not in relative_read_overrides:
            relative_read_overrides.append(value)

    conflicting_grants = set(relative_write_grants) & set(relative_read_overrides)
    if conflicting_grants:
        detail = ", ".join(sorted(conflicting_grants))
        raise ValueError(
            f"workspace grants specify both write and read for: {detail}"
        )

    lines = [
        GENERATED_HEADER.rstrip(),
        "",
        f"default_permissions = {_toml_string(PROFILE_NAME)}",
        "",
        f"[permissions.{_toml_key(PROFILE_NAME)}]",
        'extends = ":workspace"',
        "",
        f"[permissions.{_toml_key(PROFILE_NAME)}.filesystem]",
        "glob_scan_max_depth = 5",
        '":root" = "deny"',
        '":minimal" = "read"',
        '":slash_tmp" = "deny"',
    ]
    for path in sorted(allowed_read_grants, key=str):
        lines.append(f"{_toml_key(path)} = \"read\"")

    lines.extend(
        [
            "",
            f"[permissions.{_toml_key(PROFILE_NAME)}.filesystem.\":workspace_roots\"]",
            (
                '"." = "write"'
                if workspace_write_grants is None
                else '"." = "read"'
            ),
        ]
    )
    if workspace_write_grants is not None:
        for path in (
            "agent_work",
            "results",
            "results_instantiation",
            *sorted(relative_write_grants),
        ):
            lines.append(f"{_toml_key(path)} = \"write\"")
    for path in sorted(relative_read_overrides):
        lines.append(f"{_toml_key(path)} = \"read\"")
    lines.extend(
        [
            '".codex" = "read"',
            '"task_inputs" = "read"',
            '"agent_work/codex_home" = "deny"',
            '"**/*.env" = "deny"',
            "",
            f"[permissions.{_toml_key(PROFILE_NAME)}.network]",
            "enabled = false",
            "",
        ]
    )

    config_path = workspace / ".codex" / "config.toml"
    config_path.parent.mkdir(parents=True, exist_ok=True)
    config_path.write_text("\n".join(lines), encoding="utf-8")
    return config_path


def load_host_bootstrap_config(host_config: Path | None) -> dict[str, object]:
    """Return safe user-layer defaults needed before project config can load."""
    if host_config is None or not host_config.is_file():
        return {}
    data = tomllib.loads(host_config.read_text(encoding="utf-8"))
    copied: dict[str, object] = {}
    for key in BOOTSTRAP_TOP_LEVEL_KEYS:
        if key in data:
            copied[key] = data[key]
    if "model_providers" in data:
        copied["model_providers"] = data["model_providers"]
    return copied


def write_codex_home_bootstrap(
    codex_home: Path,
    *,
    workspace: Path,
    host_config: Path | None = None,
) -> Path:
    """Write minimal user-layer config that trusts exactly one generated workspace."""
    codex_home = codex_home.expanduser().resolve()
    workspace = workspace.expanduser().resolve()
    config_path = codex_home / "config.toml"
    config_path.parent.mkdir(parents=True, exist_ok=True)
    host_defaults = load_host_bootstrap_config(host_config)
    lines = [
        GENERATED_HEADER.rstrip(),
        "",
        "project_root_markers = []",
    ]
    for key in BOOTSTRAP_TOP_LEVEL_KEYS:
        if key in host_defaults:
            lines.append(f"{key} = {_toml_value(host_defaults[key])}")
    lines.extend(
        [
            "",
            f"[projects.{_toml_key(workspace)}]",
            'trust_level = "trusted"',
        ]
    )
    model_providers = host_defaults.get("model_providers")
    if isinstance(model_providers, Mapping):
        for provider, provider_config in sorted(model_providers.items()):
            if isinstance(provider_config, Mapping):
                _append_toml_table(
                    lines,
                    provider_config,
                    path=["model_providers", str(provider)],
                )
    lines.append("")
    config_path.write_text("\n".join(lines), encoding="utf-8")
    return config_path
